import "dotenv/config";
import { createCodeGenChain } from "./chains/codeGenChain.js";

/**
 * Validates the raw code string generated by the LLM against AuraGen's strict safety
 * and architectural requirements.
 *
 * @param {string} code - The extracted React code string
 * @returns {{ isValid: boolean, error?: string }}
 */
export function validateGeneratedCode(code) {
  if (!code || typeof code !== "string" || code.trim().length === 0) {
    return {
      isValid: false,
      error: "Output is empty or not a string."
    };
  }

  const trimmed = code.trim();

  // Rule 1: Must contain a default export
  const hasDefaultExport =
    /export\s+default\s+(function|class|\w+)/.test(trimmed) ||
    /export\s*\{\s*[^}]*\bas\s+default\b/.test(trimmed) ||
    trimmed.includes("export default");

  if (!hasDefaultExport) {
    return {
      isValid: false,
      error: "Code does not contain a default export ('export default function ...')."
    };
  }

  // Rule 2: No eval() or new Function()
  if (/\beval\s*\(/.test(trimmed)) {
    return {
      isValid: false,
      error: "Code contains forbidden 'eval()' dynamic execution."
    };
  }

  if (/\bnew\s+Function\s*\(/.test(trimmed)) {
    return {
      isValid: false,
      error: "Code contains forbidden 'new Function()' constructor."
    };
  }

  // Rule 3: No network calls (fetch, axios, XMLHttpRequest)
  if (/\bfetch\s*\(/.test(trimmed)) {
    return {
      isValid: false,
      error: "Code contains forbidden 'fetch()' network request."
    };
  }

  if (/\b(XMLHttpRequest|axios)\b/.test(trimmed)) {
    return {
      isValid: false,
      error: "Code contains forbidden external network client (XMLHttpRequest/axios)."
    };
  }

  // Rule 4: No direct DOM/window global access
  if (/\b(window\.|document\.|localStorage\.|sessionStorage\.)/.test(trimmed)) {
    return {
      isValid: false,
      error: "Code contains forbidden direct browser global references (window, document, storage)."
    };
  }

  // Rule 5: Basic sanity check for JSX/React component structure
  if (!trimmed.includes("return") || (!trimmed.includes("<") && !trimmed.includes("/>"))) {
    return {
      isValid: false,
      error: "Code does not appear to contain a valid React component return statement with JSX."
    };
  }

  return { isValid: true };
}

/**
 * Generates an adaptive, self-healing React component based on user friction telemetry.
 * Retries up to `maxRetries` (default: 2) if output is empty or missing a default export.
 *
 * @param {object} params
 * @param {string} params.activeField - The field name where cognitive friction occurred
 * @param {Array|object} params.formFields - Schema / list of fields from the original static form
 * @param {object} [params.userInput={}] - Key-value map of data already entered by the user
 * @param {number} params.score - Cognitive Load Score (0-100)
 * @param {object} [options={}] - Optional configuration overrides
 * @param {number} [options.maxRetries=2] - Maximum number of retries (total attempts = maxRetries + 1)
 * @param {string} [options.apiKey] - OpenAI API Key override
 * @param {string} [options.modelName] - OpenAI Model override (default: "gpt-4o")
 * @param {object} [options.customChain] - Pre-instantiated runnable chain (for testing/mocking)
 * @param {object} [options.logger=console] - Custom logger
 * @returns {Promise<string>} The validated raw React component code string
 */
export async function generateComponent(
  { activeField, formFields, userInput = {}, score },
  options = {}
) {
  // Input validation
  if (!activeField || typeof activeField !== "string") {
    throw new Error("Missing or invalid 'activeField' parameter. Must be a non-empty string.");
  }
  if (!formFields) {
    throw new Error("Missing 'formFields' parameter. Must provide original form fields.");
  }
  if (score === undefined || score === null || typeof score !== "number") {
    throw new Error("Missing or invalid 'score' parameter. Must be a numeric Cognitive Load Score (0-100).");
  }

  const logger = options.logger || console;
  const maxRetries = options.maxRetries ?? Number(process.env.MAX_RETRIES ?? 2);
  const totalAttempts = maxRetries + 1;

  // Prepare serialization of form context
  const formFieldsJson =
    typeof formFields === "string" ? formFields : JSON.stringify(formFields, null, 2);
  const userInputJson =
    typeof userInput === "string" ? userInput : JSON.stringify(userInput, null, 2);

  // Initialize or retrieve the chain
  const runnableChain =
    options.customChain ||
    createCodeGenChain({
      apiKey: options.apiKey,
      modelName: options.modelName
    }).chain;

  let attempt = 0;
  let retryFeedback = "";
  let lastError = null;

  while (attempt < totalAttempts) {
    attempt++;
    const isRetry = attempt > 1;

    if (isRetry) {
      logger.warn(
        `[AuraGen Code-Gen] Retry ${attempt - 1}/${maxRetries} triggered for activeField="${activeField}"`
      );
    } else {
      logger.info(
        `[AuraGen Code-Gen] Initiating component generation (activeField="${activeField}", score=${score})`
      );
    }

    try {
      // Invoke LangChain pipeline
      const rawCode = await runnableChain.invoke({
        activeField,
        score,
        formFieldsJson,
        userInputJson,
        retryFeedback
      });

      // Validate output against architectural and safety constraints
      const validation = validateGeneratedCode(rawCode);

      if (validation.isValid) {
        logger.info(
          `[AuraGen Code-Gen] Successfully generated valid React component on attempt ${attempt}/${totalAttempts}`
        );
        return rawCode;
      }

      // If invalid, record error and prepare feedback for retry
      lastError = new Error(`Validation failed: ${validation.error}`);
      logger.warn(
        `[AuraGen Code-Gen] Attempt ${attempt}/${totalAttempts} rejected: ${validation.error}`
      );

      retryFeedback = `\n\n⚠️ PREVIOUS ATTEMPT REJECTED: ${validation.error}\nYou MUST generate a complete functional React component that includes 'export default function DynamicFormWizard(props) { ... }' with pure Tailwind CSS classes and zero external imports or network calls.`;
    } catch (invokeError) {
      lastError = invokeError;
      logger.error(
        `[AuraGen Code-Gen] Error during model invocation on attempt ${attempt}/${totalAttempts}:`,
        invokeError.message
      );

      retryFeedback = `\n\n⚠️ PREVIOUS INVOCATION ERROR: ${invokeError.message}\nPlease ensure the output is exclusively formatted as a valid React component inside \`\`\`jsx ... \`\`\` code fences.`;
    }
  }

  // All attempts exhausted
  throw new Error(
    `[AuraGen Code-Gen] Failed to generate a valid React component after ${totalAttempts} attempt(s). Last error: ${lastError?.message || "Unknown error"}`
  );
}

